### Counting Odd Numbers in a Singly Linked List

#### 1. Pseudocode:

```text
Algorithm CountOddNodes(Head):
    Input: Head pointer of a Singly Linked List L
    Output: Total count of nodes containing odd integer data

    Step 1: Set count = 0
    Step 2: Set current = Head
    Step 3: While current != NULL do
                If current.data % 2 != 0 then
                    count = count + 1
                End If
                current = current.next
            End While
    Step 4: Return count

```

#### 2. C Implementation:

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

int countOddNumbers(struct Node* head) {
    int count = 0;
    struct Node* current = head;
    while (current != NULL) {
        // Check if data is odd (handles negative integers via != 0)
        if (current->data % 2 != 0) {
            count++;
        }
        current = current->next;
    }
    return count;
}

// Example: 15 -> 8 -> 21 -> 4 -> 33 -> NULL
// Odd numbers: 15, 21, 33 => Output = 3

```

**Complexity:**
- **Time Complexity:** $O(n)$ — Single pass through all $n$ nodes.
- **Space Complexity:** $O(1)$ — Only an accumulator variable `count` is stored.

### Matrix Multiplication Using Dynamic Memory Allocation in C

```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    int r1, c1, r2, c2;

    // 2. Input dimensions
    printf("Enter rows and columns for Matrix A: ");
    scanf("%d %d", &r1, &c1);
    printf("Enter rows and columns for Matrix B: ");
    scanf("%d %d", &r2, &c2);

    if (c1 != r2) {
        printf("Error: Matrix multiplication impossible! Columns of A (%d) != Rows of B (%d).\n", c1, r2);
        return 1;
    }

    // 1. Allocate memory dynamically
    int **A = (int **)malloc(r1 * sizeof(int *));
    for (int i = 0; i < r1; i++) A[i] = (int *)malloc(c1 * sizeof(int));

    int **B = (int **)malloc(r2 * sizeof(int *));
    for (int i = 0; i < r2; i++) B[i] = (int *)malloc(c2 * sizeof(int));

    int **C = (int **)malloc(r1 * sizeof(int *));
    for (int i = 0; i < r1; i++) C[i] = (int *)malloc(c2 * sizeof(int));

    // Input elements for Matrix A
    printf("\nEnter elements of Matrix A (%dx%d):\n", r1, c1);
    for (int i = 0; i < r1; i++) {
        for (int j = 0; j < c1; j++) {
            scanf("%d", &A[i][j]);
        }
    }

    // Input elements for Matrix B
    printf("\nEnter elements of Matrix B (%dx%d):\n", r2, c2);
    for (int i = 0; i < r2; i++) {
        for (int j = 0; j < c2; j++) {
            scanf("%d", &B[i][j]);
        }
    }

    // 3. Perform Matrix Multiplication: C = A x B
    for (int i = 0; i < r1; i++) {
        for (int j = 0; j < c2; j++) {
            C[i][j] = 0;
            for (int k = 0; k < c1; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    // 4. Display Resulting Matrix C
    printf("\n--- Resulting Matrix C (Product A x B) ---\n");
    for (int i = 0; i < r1; i++) {
        for (int j = 0; j < c2; j++) {
            printf("%6d ", C[i][j]);
        }
        printf("\n");
    }

    // Clean up dynamic memory
    for (int i = 0; i < r1; i++) free(A[i]);
    free(A);
    for (int i = 0; i < r2; i++) free(B[i]);
    free(B);
    for (int i = 0; i < r1; i++) free(C[i]);
    free(C);

    return 0;
}
```

### Student Academic Records System

```c
#include <stdio.h>

#define NUM_STUDENTS 5
#define NUM_SUBJECTS 3

// a. Structure Student
struct Student {
    int studentId;
    char name[50];
    float grades[NUM_SUBJECTS]; // 0: Math, 1: Science, 2: English
    float averageGrade;
};

int main() {
    // b. (i) Array of Student structures
    struct Student s[NUM_STUDENTS];
    int topStudentIndex = 0;
    float highestAverage = -1.0;

    // b. (ii) User input for each student
    printf("Enter Academic Records for %d Students:\n", NUM_STUDENTS);
    for (int i = 0; i < NUM_STUDENTS; i++) {
        printf("\n--- Student %d ---\n", i + 1);
        printf("Enter Student ID: ");
        scanf("%d", &s[i].studentId);
        printf("Enter Name: ");
        scanf(" %[^\n]", s[i].name);
        printf("Enter Grades in Math, Science, English: ");
        scanf("%f %f %f", &s[i].grades[0], &s[i].grades[1], &s[i].grades[2]);

        // b. (iii) Compute average grade
        s[i].averageGrade = (s[i].grades[0] + s[i].grades[1] + s[i].grades[2]) / NUM_SUBJECTS;

        // b. (iv) Track student with highest average
        if (s[i].averageGrade > highestAverage) {
            highestAverage = s[i].averageGrade;
            topStudentIndex = i;
        }
    }

    // Display student averages
    printf("\n================ Student Academic Records ================\n");
    printf("%-8s %-20s %-8s %-8s %-8s %-10s\n", 
           "ID", "Name", "Math", "Science", "English", "Average");
    printf("----------------------------------------------------------\n");
    for (int i = 0; i < NUM_STUDENTS; i++) {
        printf("%-8d %-20s %-8.1f %-8.1f %-8.1f %-10.2f\n",
               s[i].studentId, s[i].name,
               s[i].grades[0], s[i].grades[1], s[i].grades[2],
               s[i].averageGrade);
    }

    // Display top student
    printf("==========================================================\n");
    printf("Top Performing Student:\n");
    printf("ID: %d | Name: %s | Highest Average Grade: %.2f\n",
           s[topStudentIndex].studentId, 
           s[topStudentIndex].name, 
           s[topStudentIndex].averageGrade);

    return 0;
}
```

### Polynomial Difference and Maximum Difference Term

#### Pseudocode Routine:

```text
Structure Term:
    coeff: Integer
    exp: Integer
End Structure

Algorithm PolynomialDifferenceAnalysis():
    // a) Get the maximum power (degree) of two polynomials
    Print "Enter maximum power (degree) for Polynomial A: "
    Read maxPowerA
    Print "Enter maximum power (degree) for Polynomial B: "
    Read maxPowerB
    maxDegree = Max(maxPowerA, maxPowerB)

    // Create coefficient arrays of size (maxDegree + 1) initialized to 0
    Array polyA[0 ... maxDegree] = {0}
    Array polyB[0 ... maxDegree] = {0}
    Array diff[0 ... maxDegree] = {0}

    // b) Get input for coefficients and exponents for Polynomial A and B
    Print "Enter number of terms for Polynomial A: "
    Read numTermsA
    For i = 1 to numTermsA do
        Read coeff, exp
        polyA[exp] = polyA[exp] + coeff
    End For

    Print "Enter number of terms for Polynomial B: "
    Read numTermsB
    For i = 1 to numTermsB do
        Read coeff, exp
        polyB[exp] = polyB[exp] + coeff
    End For

    // c) Calculate the difference in coefficients value (A - B) in each term
    For exp = 0 to maxDegree do
        diff[exp] = polyA[exp] - polyB[exp]
    End For

    // d) Display the term which has the maximum difference
    maxDiffValue = -Infinity
    maxDiffExp = -1

    For exp = 0 to maxDegree do
        // Absolute or algebraic difference (taking magnitude |polyA[exp] - polyB[exp]|)
        absDiff = Absolute(diff[exp])
        If absDiff > maxDiffValue then
            maxDiffValue = absDiff
            maxDiffExp = exp
        End If
    End For

    Print "Term with Maximum Difference: "
    Print "Exponent: ", maxDiffExp, 
          " | Coefficient Difference (A - B): ", diff[maxDiffExp], 
          " | Magnitude: ", maxDiffValue
End Algorithm

```

#### C Implementation Snippet:

```c
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int main() {
    int degA, degB;
    printf("Enter max degree of Polynomial A and B: ");
    scanf("%d %d", &degA, &degB);
    int maxDeg = (degA > degB) ? degA : degB;

    int *A = (int *)calloc(maxDeg + 1, sizeof(int));
    int *B = (int *)calloc(maxDeg + 1, sizeof(int));
    int *diff = (int *)calloc(maxDeg + 1, sizeof(int));

    int termsA, termsB, c, e;
    printf("Enter number of terms in A: ");
    scanf("%d", &termsA);
    for (int i = 0; i < termsA; i++) {
        scanf("%d %d", &c, &e);
        A[e] = c;
    }

    printf("Enter number of terms in B: ");
    scanf("%d", &termsB);
    for (int i = 0; i < termsB; i++) {
        scanf("%d %d", &c, &e);
        B[e] = c;
    }

    int maxDiff = -1, maxExp = 0;
    for (int exp = 0; exp <= maxDeg; exp++) {
        diff[exp] = A[exp] - B[exp];
        if (abs(diff[exp]) > maxDiff) {
            maxDiff = abs(diff[exp]);
            maxExp = exp;
        }
    }

    printf("\nMaximum difference occurs at term with power %d: Difference = %d\n", maxExp, diff[maxExp]);
    free(A); free(B); free(diff);
    return 0;
}
```

### Neighbor Sum in a Doubly Linked List (DLL)

#### Problem Description:
For each node in a Doubly Linked List:
$$\text{Neighbor Sum} = \text{prev.data} + \text{next.data}$$
If a node is the head (`prev == NULL`), consider `prev.data = 0`.  
If a node is the tail (`next == NULL`), consider `next.data = 0`.

#### Example Trace:
Given list: `[10] <=> [20] <=> [30] <=> [40]`
- For node `10`: `prev = 0`, `next = 20` $\implies \text{Sum} = 0 + 20 = 20$
- For node `20`: `prev = 10`, `next = 30` $\implies \text{Sum} = 10 + 30 = 40$
- For node `30`: `prev = 20`, `next = 40` $\implies \text{Sum} = 20 + 40 = 60$
- For node `40`: `prev = 30`, `next = 0` $\implies \text{Sum} = 30 + 0 = 30$

#### C Program:

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* prev;
    struct Node* next;
};

struct Node* createNode(int val) {
    struct Node* n = (struct Node*)malloc(sizeof(struct Node));
    n->data = val;
    n->prev = NULL;
    n->next = NULL;
    return n;
}

void displayNeighborSums(struct Node* head) {
    if (head == NULL) {
        printf("List is empty.\n");
        return;
    }

    printf("%-12s %-12s %-12s %-15s\n", "Node Data", "Prev Data", "Next Data", "Neighbor Sum");
    printf("---------------------------------------------------\n");

    struct Node* curr = head;
    while (curr != NULL) {
        int prevVal = (curr->prev != NULL) ? curr->prev->data : 0;
        int nextVal = (curr->next != NULL) ? curr->next->data : 0;
        int sum = prevVal + nextVal;

        printf("%-12d %-12d %-12d %-15d\n", curr->data, prevVal, nextVal, sum);
        curr = curr->next;
    }
}

int main() {
    // Creating Doubly Linked List: 10 <=> 20 <=> 30 <=> 40
    struct Node* n1 = createNode(10);
    struct Node* n2 = createNode(20);
    struct Node* n3 = createNode(30);
    struct Node* n4 = createNode(40);

    n1->next = n2; n2->prev = n1;
    n2->next = n3; n3->prev = n2;
    n3->next = n4; n4->prev = n3;

    displayNeighborSums(n1);
    return 0;
}

```

**Complexity:** Time Complexity: $O(n)$, Space Complexity: $O(1)$.
